            aOrbiterD = RotL64((aOrbiterD * 0xE195D9BAC4AF089BULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xDD183947091D71F9ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xD01F5D6F36138482ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x87C3D1551F1B9AFDULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0xC11E238F01E4CD2EULL;
