            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0x33E26AD18C43265BULL) + aOUSaltD[((aIndex + 343U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0xBC6220826786FA0EULL;
