            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterH) + 0x37AA3E640ADEADDBULL) + aNonceWordI;
            aOrbiterK = ((aOrbiterK ^ aOrbiterJ) ^ 0x5B1711696454277EULL) ^ aOUSaltE[(((511U - aIndex) + 339U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xD2EABAF1730C61F3ULL), 23U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0xBE3BE7C55DA5ADE5ULL) + aNonceWordN;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xDC2B9B9439BD70FBULL;
