            aWandererG = aWandererG + ((((RotL64(aCross, 47U) + RotL64(aOrbiterI, 57U)) + aOrbiterD) + RotL64(aCarry, 29U)) + aWUSaltH[(((511U - aIndex) + 327U)) & S_SALT1]);
