            //
            aIngress = (RotL64(aWindLaneA[((aIndex + 1555U)) & S_BLOCK1], 38U) ^ RotL64(aWindLaneB[((aIndex + 2300U)) & S_BLOCK1], 27U));
            aIngress ^= RotL64(aKineticLaneC[((aIndex + 365U)) & S_BLOCK1], 5U);
