            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterG) + 0x9F6FC989130194BBULL) + aNonceWordC;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xA90A7BBEBF467BF4ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x72593C3848DB8E39ULL), 39U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0x38C48BB669F61107ULL;
